@startuml

enum ItemCategory {
  BabyClothing
  WomenWinterBoots
  Fridge
  Microwave
  // ... (other categories)
}

class Resident {
  + Name : string
  + StreetAddress : string
  + PhoneNumber : string
  + EmailAddress : string
  + ItemsDescription : string
}

class PickupVehicle {
  + LicensePlateNumber : string
  + StorageSpace : int
  + AvailableDays : date[]
}

class VolunteerDriver {
  + Name : string
  + AvailableDays : date[]
}

class DistributionCenter {
  + Address : string
}

class FoodBank {
  + Address : string
}

class H2SEmployee {
  + FirstName : string
  + LastName : string
  + RFIDDevice : bool
}

class PickupRoute {
  + Date : date
}

class ScheduledPickup {
  + StartTime : time
  + EndTime : time
  + Dimension : int
  + Weight : int
}

class Item {
  + Description : string
  + Category : ItemCategory[]
  + RFIDTagged : bool
}

class Client {
  + Name : string
  + StreetAddress : string
  + NeededCategories : ItemCategory[]
}

class Delivery {
  + Address : string
  + PickupRoute : PickupRoute
}

PickupVehicle "1" -- "*" ScheduledPickup
VolunteerDriver "0..*" -- "*" PickupRoute
DistributionCenter "1" -- "*" Item
FoodBank "1" -- "*" Item
H2SEmployee "1" -- "*" Item
Client "0..*" -- "*" Delivery

@enduml

